fn is_greater(n: i32, a: Vec<i32>) -> bool {
    // Iterate through each element in the vector.
    // If we find any element that is greater than or equal to `n`,
    // we can immediately return false.
    for x in a {
        if n <= x {
            return false;
        }
    }
    // If we never found such an element, `n` is strictly greater
    // than every element (or the vector was empty), so return true.
    true
}

fn main() {
    let empty: Vec<i32> = vec![];
    assert_eq!(is_greater(5, empty), true);

    let v1 = vec![1, 2, 3];
    assert_eq!(is_greater(5, v1), true);

    let v2 = vec![1, 5, 3];
    assert_eq!(is_greater(5, v2), false);

    let v3 = vec![6, 7, 8];
    assert_eq!(is_greater(5, v3), false);

    println!("All tests passed!");
}